export default function MinecraftGame() {
  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    oxygen,
